"""Turn 35 Wave 92: THE STOP-CHASE CONTROL, THE STAMINA-CONSERVATION TRICK, AND AN EIGHTH REJECTION.

Wave 92's centrepieces:

1. THE AUTOMATIC CHASE-DOWN, and the fact that it WASTES STAMINA. When a keeper sweeps the ball
   away in desperation, or when players are pressed, the game auto-chases - and every auto-chase
   burns energy you did not choose to spend. There is a stop-chase control for it, and knowing
   that is a stamina lever the corpus did not have.

2. THE STAMINA-CONSERVATION TRICK, which links two corpus findings that had not been connected:
   the 5:0 Dream Points cap and the stamina economy. **Once you are five goals up, there is no
   DP left to win - so give the ball to your highest-CON player and dribble in a small area near
   the touchline, turning back to avoid tackles.** You keep possession, burn almost no stamina,
   and the match is already won.

3. PLAYDREAMLEAGUESOCCER.COM REJECTED AN EIGHTH TIME - and this is the most elaborate
   fabrication yet: a complete fake DLS 2026 fixture calendar with dates and coin prize pools
   for a "Global Super League", a "Youth Academy Cup", a "Champions Cup", an "Elite Showdown",
   a "Diwali Festival Event" and a "Christmas Charity Shield". None of it exists.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w92')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

